class Solution:
    def numSpecialEquivGroups(self, words: List[str]) -> int:
        def sig(s):
            return (''.join(sorted(s[::2])), ''.join(sorted(s[1::2])))
        seen = set()
        for w in words:
            seen.add(sig(w))
        return len(seen)

