class Solution {
public:
    int numSpecialEquivGroups(vector<string>& words) {
        auto sig = [](const string& s) {
            string e, o;
            for (int i = 0; i < (int)s.size(); ++i)
                (i % 2 ? o : e) += s[i];
            sort(e.begin(), e.end());
            sort(o.begin(), o.end());
            return e + '#' + o;
        };
        unordered_set<string> seen;
        for (auto& w : words) seen.insert(sig(w));
        return seen.size();
    }
};

