        seen = set()
        for w in words:
            even = [0] * 26
            odd = [0] * 26
            for i, c in enumerate(w):
                if i % 2 == 0:
                    even[ord(c) - 97] += 1
                else:
                    odd[ord(c) - 97] += 1
            seen.add((tuple(even), tuple(odd)))
        return len(seen)

